package buyi

var Hexagrams = []Hexagram{
	{Number: 1, Name: "乾为天", HumanWay: "上乾下乾为二金比和，纯阳之象。刚健不知疲惫，正直无私，心胸宽阔，有领导才能。但孤阳不生，对家人不重情意，女命主克子伤妻。得运时名利双收，失运时孤寡。", ImageReading: "官人登梯望月（蟾宫折桂，平步青云）、鹿在云中（不可求禄（禄自至））、人琢玉（坚心不移，小心戒盛）、月当空（大光明）。"},
	{Number: 2, Name: "坤为地", HumanWay: "上坤下坤为二土比和，无阳气，孤阴不生，男得此卦主寿短，亦主子嗣艰难。坤为柔为包容，助人为乐、慈悲而严厉，保守、不善管理，但有始有终，终获成就。坤为母、护子之心，有时不讲道理。", ImageReading: "金甲神抛文书给官人（文字得神力相助，有利学业）、马回头（禄马，柔顺）、十一口（繁体陈姓）（吉字）、人坐看一堆钱（贵人，欲拿不得，忧心忡忡）。"},
	{Number: 3, Name: "水雷屯", HumanWay: "万物始生，创业维艰。绝对不要盲目进取，此时最需要\"建侯\"——寻找得力助手和靠山。舟在滩头意味着寸步难行，要像犬在地下一样忍辱负重。一切刚开始的时候，千万不能急。人有病榻说明有难，但一旁有官人说明有救星。", ImageReading: "舟在滩头（寸步难行）、犬在地下（忍辱负重）、人躺病榻（处境艰难）、官人在旁（贵人来救）。"},
	{Number: 4, Name: "山水蒙", HumanWay: "童蒙无知，启蒙之道。倪师非常强调\"发蒙\"——求教要诚心。占卜\"初筮告，再三渎，渎则不告\"：只问一次，神明会告诉你；反复问同一件事，就是不敬，神灵不理你。阴雨天代表暂时迷茫，但一阵风来就晴天，说明困顿不会太久。", ImageReading: "阴雨天（迷茫）、小儿在桥上（求学之路）、果实落地（成熟可摘）、官人指路（贵人引路）。"},
	{Number: 5, Name: "水天需", HumanWay: "守正待时，饮食宴乐。危险（坎水）在前面，不要硬冲。在家里好吃好喝、充实自己，等待时机。龙在井底是困顿之象，但龙不是井底之蛙，总有一飞冲天的时候。", ImageReading: "阴雨连绵（时机未到）、文字在空中（口说无凭）、龙在井底（暂时困顿）、人在险处（有危险）。"},
	{Number: 6, Name: "天水讼", HumanWay: "利见大人，谋始防争。\"讼\"源于做事的开始没有讲好规矩。倪师强调：如果要打官司，必须找公正的第三方（大人）来解决争端，不要私下硬碰。天水背离，天往上，水往下，所以矛盾。", ImageReading: "财帛落地（损失财产）、二人相争（口舌是非）、官人在侧（需第三方裁决）。"},
	{Number: 7, Name: "地水师", HumanWay: "容民畜众，统帅之道。兵圣之卦。\"师\"就是打仗。必须\"长子帅师\"——重用有经验的干将，忌用小人。师徒相随的符号说明团队的重要性。", ImageReading: "师徒相随（团队作战）、军旗（纪律严明）、马在险处（有惊无险）。"},
	{Number: 8, Name: "水地比", HumanWay: "亲辅依附，社交之道。\"比\"是亲比、抱团。\"后夫凶\"——跟从别人、做决定要快，迟到的人没有好下场。倪师举做生意合伙：看准了马上投，拖拖拉拉最后什么都得不到。", ImageReading: "众人相聚（社交结盟）、水在地上（亲密无间）、贵人扶持（得遇贵人）。"},
	{Number: 9, Name: "风天小畜", HumanWay: "积蓄力量，密云不雨。力量还不够（小畜），没办法大打出手。此时只能做小型的投资、学习和蓄养。密云在天却不下雨——时机未至。鸟在笼中代表行动受限。", ImageReading: "密云在天（时机未至）、鸟在笼中（行动受限）、夫妻反目（小畜有阻碍）。"},
	{Number: 10, Name: "天泽履", HumanWay: "履行、礼仪，如履薄冰。倪师讲这卦叫\"履虎尾\"——跟在老虎后面走。如何不被咬？唯有靠\"礼\"和规矩。在险处的符号意味着人在危险的边缘试探，需要极其小心。", ImageReading: "走在险处（如履薄冰）、官人带剑（威严）、印章在地上（权力不稳）。"},
	{Number: 11, Name: "地天泰", HumanWay: "上下交通，泰平盛世。阴阳交泰——在家里是丈夫体贴、妻子贤惠；在公司是老板和员工一条心。三人同行说明有人支持，喜报代表好消息，日月同辉是大吉之象。但泰卦之后紧接着就是否卦，所以要\"安而不忘危\"。", ImageReading: "三人同行（有支持者）、喜报（好消息）、日月同辉（大吉）。"},
	{Number: 12, Name: "天地否", HumanWay: "闭塞不通，小人当道。\"否\"就是鸡同鸭讲，上下不买账。此时君子要韬光养晦，不可强出头。官人射鹿代表丈夫取禄；文书摇摇欲坠说明事业不稳；二人执索表示互相牵累。", ImageReading: "官人射鹿（丈夫取禄）、文书摇摇欲坠（事业不稳）、二人执索（互相牵累）、黑舌（口舌是非）。"},
	{Number: 13, Name: "天火同人", HumanWay: "天下大同，旷野之聚。抛弃私心，为了共同的目标与天下人合作，最利于开展团队项目。众人聚会、光明在天、大路通天的卦图说明此卦是一个可以大有作为的时机。", ImageReading: "众人聚会（合作共赢）、光明在天（前景光明）、大路通天（前途无量）。"},
	{Number: 14, Name: "火天大有", HumanWay: "顺天依时，富有四海。盛大之时，倪师强调要\"抑恶扬善\"——千万不能骄做，要懂得散财、回馈社会。日丽中天、满载而归之象。大有最大的忌讳是\"满招损\"。", ImageReading: "日丽中天（鼎盛时期）、满载而归（富有）、财宝如山（丰盛）。"},
	{Number: 15, Name: "地山谦", HumanWay: "内高外卑，谦逊笃实。倪师极推崇此卦——真正的才华要隐藏在朴素的外表下。\"鬼神害盈而福谦\"：鬼神讨厌骄做的人，喜欢谦卑的人。高山平地——外面低调，内心实力。", ImageReading: "高山平地（内高外低）、官人作揖（谦逊态度）、低调获吉。"},
	{Number: 16, Name: "雷地豫", HumanWay: "顺时依势，安乐喜悦。顺应民心而动，自然皆大欢喜。雷出地奋就是春雷惊蛰之象——冬去春来万物复苏。但倪师提醒\"豫\"不可流于沉迷逸乐，乐极必生悲。", ImageReading: "雷出地奋（春雷惊蛰）、张乐设宴（欢乐景象）。"},
	{Number: 17, Name: "泽雷随", HumanWay: "随物应变，择善而从。跟着对的人、对的时机走。做臣子、做员工、做善听人言的领导。\"随\"不是盲目从众，而是跟着正道走。水动随雷，顺水推舟。", ImageReading: "水动随雷（顺势而行）、众人跟随（得人拥护）、顺水推舟。"},
	{Number: 18, Name: "山风蛊", HumanWay: "振疲起衰，内部腐败。蛊就是生虫了。倪师说这是\"治乱\"之卦——发现问题要在\"先甲三日，后甲三日\"果断改革。先甲三日 = 回顾过去三天找原因；后甲三日 = 规划未来三天怎样改。器具生虫是腐烂的征兆。", ImageReading: "器具生虫（腐败象征）、乱丝难理（问题复杂）、需要大力整顿。"},
	{Number: 19, Name: "地泽临", HumanWay: "居高临下，督导管理。阳气渐长，领导视察。倪师讲临卦要\"保民无疆\"——用宽容和亲和力去管人。登高望远之象，贵人降临，官运亨通。", ImageReading: "登高望远（视野开阔）、贵人降临（机遇来临）、官运亨通。"},
	{Number: 20, Name: "风地观", HumanWay: "仰观俯察，为人表率。观光、观察。作为领导，要像风吹大地一样周游视察，同时你的德行也要让人瞻仰。风行地上——上面的人在动，下面的人在看着。领导的一言一行都是榜样。", ImageReading: "风行地上（周游视察）、高台远眺（观望评估）、静观其变。"},
	{Number: 21, Name: "火雷噬嗑", HumanWay: "治狱刑罚，咬碎障碍。噬嗑是上下颚咬合。倪师讲这是\"法治\"卦——遇到阻碍、小人，必须用雷霆手段咬碎。雷電交加本来就是天威之象，官司、牢狱、严刑峻法都与此卦相关。", ImageReading: "雷電交加（天威震撼）、咬碎骨头（克服障碍）、官司牢狱之象。"},
	{Number: 22, Name: "山火贲", HumanWay: "文饰美化，外饰内质。贲是装修、化妆。倪师说外表要包装，但内里必须真诚。过度包装就是虚伪。火照山前——山有火光映照，外显华美，但要记得山本身就是山。", ImageReading: "火照山前（外显华美）、盛装打扮（包装形象）、外表华丽。"},
	{Number: 23, Name: "山地剥", HumanWay: "阴盛阳衰，剥落危机。小人把君子剥削得只剩最后一点。倪师说此时千万别去争，这是\"硕果不食\"——留一颗最后的果子做种子，等待来年春天。高山崩塌之象是全面瓦解的预兆。", ImageReading: "高山崩塌（全面瓦解）、床脚断裂（基础不稳）、小人得势剥削。"},
	{Number: 24, Name: "地雷复", HumanWay: "一阳复始，转机重现。剥极必复，冬至一阳生。做错事了改过自新，生病了开始痊愈。倪师说\"出入无疾\"——从这个低谷走出来不会受伤。地下雷动就是能量在下面积蓄准备爆发。", ImageReading: "地下雷动（能量积蓄）、失而复得（转好）、重获新生。"},
	{Number: 25, Name: "天雷无妄", HumanWay: "顺应天命，不怀妄想。没有妄念。倪师讲无妄就是做你该做的事，别天天想着中彩票。动迁、盲动则灾。天下雷行是天雷的正常运行，但其中若有\"不正常的震动\"就是意外——天灾人祸防意外。", ImageReading: "天下雷行（自然正常）、天灾人祸（防意外）、顺其自然。"},
	{Number: 26, Name: "山天大畜", HumanWay: "大有积蓄，怀才不遇。\"不家食，吉\"——不要天天呆在家里吃老本，要去国家、大平台施展大才华。山中藏天——大智慧被山包住了，必须走出去让别人看到。", ImageReading: "山中藏天（大才被包住）、大量财富（积蓄丰厚）、招贤纳士。"},
	{Number: 27, Name: "山雷颐", HumanWay: "颐养之道，注意言行。\"观颐，自求口实\"。倪师说一要注意自己的饮食养生（物质之口），二要注意嘴巴说出来的话（言语之口），别惹祸。闭合的上下颚代表思考后再说话。", ImageReading: "闭合的上下颚（慎言慎行）、求生活动（生养生息）、谨言慎行。"},
	{Number: 28, Name: "泽风大过", HumanWay: "负荷过重，栋梁弯曲。压力太大了。倪师说这是\"大过\"之时，必须要\"独立不惧，遁世无闷\"的刚毅精神——不畏惧、不苦闷，独自扛过去。泽淹树木、房屋将倾是危局。", ImageReading: "泽淹树木（压力过大）、房屋将倾（危局时刻）、大风折树（坚持不住）。"},
	{Number: 29, Name: "坎为水", HumanWay: "重重险陷，行险用信。倪师讲坎卦是全经最险的卦。置身险境时，唯有保持内心的诚信与像水一样的坚韧，才能通过。掉入深谷、九死一生之象。坎卦最关键的是\"维心，亨\"——心诚则通。", ImageReading: "掉入深谷（身陷绝境）、重重波浪（险境迭加）、九死一生。"},
	{Number: 30, Name: "离为火", HumanWay: "附着光明，美丽聪明。火不能凭空烧，必须依附在柴火上。倪师讲\"离\"是依附——人要依附在正道、大平台上。日出东方、熊熊烈火之象。离卦在家庭中为中女，在公司代表要找到合适的直属领导。", ImageReading: "日出东方（光明初现）、熊熊烈火（热情能量）、依附正道。"},
	{Number: 31, Name: "泽山咸", HumanWay: "心灵感应，恋爱之始。少男（艮）追少女（兑），无私的感应。倪师讲人际沟通的最高境界就是\"咸\"带来的自然感应——不需要太多言语，心领神会。山上有泽，山水交融。", ImageReading: "山上有泽（阴阳交融）、男女相悦（自由恋爱）、两情相悦。"},
	{Number: 32, Name: "雷风恒", HumanWay: "夫妇长久，恒心恒久。长男（震）长女（巽），天经地义的恒久之道。倪师在风水上强调：夫妻住西北（乾）或西南（坤），若住东偏南则是长久。雷动风散，相伴到老。", ImageReading: "雷动风散（阴阳相伴）、相伴到老（不离不弃）、百年好合。"},
	{Number: 33, Name: "天山遁", HumanWay: "退避避险，惹不起躲得起。小人势头太强时，君子不与小人同流合污。太阳下山是退避的时机到了，高山远眺是要聪明的观察。抽身便走，不要恋战。", ImageReading: "太阳下山（退避之时）、高山远眺（明智观察）、抽身便走（及时止损）。"},
	{Number: 34, Name: "雷天大壮", HumanWay: "壮大刚烈，莫用暴力。雷行天上声势浩大，力量太强时（大壮），容易像公羊一样角触藩篱。倪师提醒：越强壮越要守礼，不可滥用武力，否则进退两难。", ImageReading: "雷行天上（声势浩大）、羊触藩篱（进退两难）。"},
	{Number: 35, Name: "火地晋", HumanWay: "加官进爵，光明磊落。太阳升起的时候，晋升要像太阳一样无私普照。臣子要忠诚，容易得到提拔。太阳出地、步步升高之象。", ImageReading: "太阳出地（升迁开始）、接见封赏（受到赏识）、步步高升。"},
	{Number: 36, Name: "地火明夷", HumanWay: "晦暗受伤，韬光养晦。太阳落入地下。倪师说这是君子落难之时。此时要\"内文明而外柔顺\"——装傻（如箕子）以自全。受伤、黑暗、隐忍之象。此卦遇之表示有大才智但不被看到，需要等待时机。", ImageReading: "太阳下地（光明被掩盖）、受伤黑暗（处境不利）、隐忍装傻（保全之道）。"},
	{Number: 37, Name: "风火家人", HumanWay: "治家之道，女主内男主外。家和万事兴。倪师极其看重家人卦——长幼尊卑，各安其位。家法严明，家道乃成。风自火出——家人的和睦是从内心的温暖散发出来的。", ImageReading: "风自火出（和睦温暖）、一家团聚（家和万事兴）、治家有方。"},
	{Number: 38, Name: "火泽睽", HumanWay: "同而求异，离心离德。二女同居而志不同。倪师讲大家意见不合（睽）时，要在大方向上求同，小地方存异。火向上、泽向下——背道而驰之象。", ImageReading: "火上泽下（背道而驰）、两相猜忌（口舌是非）。"},
	{Number: 39, Name: "水山蹇", HumanWay: "寸步难行，见险而止。前有大水，后有高山。\"蹇\"就是跛脚，走不动了。这个时候硬冲必死，必须停下来找贵人帮忙。大雪满山之象——路被大雪封住。", ImageReading: "大雪满山（前路断绝）、寸步难行（行动受阻）、跛足难行。"},
	{Number: 40, Name: "雷水解", HumanWay: "缓解冰释，既往不咎。险难解除了。倪师讲雷雨之后万物舒解，此时问题解决了，就要抓紧恢复生产。对过去的恩怨既往不咎。网开一面——不要揪着过去不放。", ImageReading: "雷雨大作（雨过天晴）、冰雪消融（危难过去）、解脱之象。"},
	{Number: 41, Name: "山泽损", HumanWay: "损己利人，克制欲望。惩忿窒欲。倪师说\"损\"不一定是坏事——减少自己的私欲，或者先付出、先亏本，后面才有大益。减损深泽表示要有舍有得。", ImageReading: "减损深泽（有舍有得）、供奉付出（克己奉公）。"},
	{Number: 42, Name: "风雷益", HumanWay: "损上益下，普施恩泽。看到别人有困难，从上面拿出来补贴下面。倪师讲做老板的此时要给员工发奖金、做公益，大吉。风雷相激产生的是双重的增益能量。", ImageReading: "风雷相激（双重增益）、获利分红（双赢）。"},
	{Number: 43, Name: "泽天夬", HumanWay: "决断除恶，光明正大。到了和极少数小人决战的时候。倪师说不可以用阴暗手段，要光明正大地公布其罪状，果断切断。泽水决堤——一泻千里，不可回头。", ImageReading: "泽水决堤（推枯拉朽）、一决雌雄（临门一脚）、斩断关联。"},
	{Number: 44, Name: "天风姤", HumanWay: "邂逅相遇，防范小人之初生。一阴始生——一个坏的苗头出现了。倪师在《天纪》中常讲姤卦是\"不期而遇\"。若测婚姻遇此卦，主女方过于刚强，不易长久。天风相遇，风吹云散——缘分来得快去得也快。倪师在阳宅中特别指出：主卧在东南为天风姤，夫婿犯桃花，姤为男女交合象。", ImageReading: "天下有风（萍水相逢）、防微杜渐（小人之初生）。"},
	{Number: 45, Name: "泽地萃", HumanWay: "荟萃聚集，提防争夺。物以类聚，人以群分。聚在一起的时候，一定要\"除戎器，戒不虞\"——人多是非多，要提防内乱。鱼龙汇聚之象也是聚宝盆——集才有收获，但要防止内部争斗。", ImageReading: "鱼龙汇聚（人才聚集）、聚宝盆（集才有收获）、众人聚集。"},
	{Number: 46, Name: "地风升", HumanWay: "稳步上升，积小成大。地中生木。\"柔顺向上\"——不是暴发户，而是靠着贤人和自己的不断积累，慢慢爬上高位。树木破土之象，积少成多。", ImageReading: "树木破土（由小到大）、稳步高升（不是暴发）、官员升迁。"},
	{Number: 47, Name: "泽水困", HumanWay: "身处困境，考验操守。泽中无水，水漏光了。倪师说这是人生的大考验。穷困潦倒时，小人会怨天尤人；君子则\"致命遂志\"——接受命运，坚持操守，等待时机。水干鱼死是最绝望的象征。", ImageReading: "水干鱼死（资源枯竭）、身陷囹圄（被困住）、穷途末路。"},
	{Number: 48, Name: "水风井", HumanWay: "源泉不竭，守常不动。改邑不改井。倪师讲井卦代表你有一技之长、有不变的本领（井德）——别人都来求你，但你必须保持清澈。木桶汲水之象：你有好水，别人自然会来打。", ImageReading: "木桶汲水（资源被取用）、源源不断（本领持久）、求贤问计。"},
	{Number: 49, Name: "泽火革", HumanWay: "变革改制，顺天应人。水火相克，必须要变革。倪师讲\"革\"的时机很重要，要等到\"巳日乃孚\"——大家都信任你、时机成熟了再动手。水浇在火上必然产生大变动，这是巨变的卦象。", ImageReading: "水火相荡（大变即将发生）、翻天覆地（不可逆转）、改朝换代。"},
	{Number: 50, Name: "火风鼎", HumanWay: "执鼎建立，三人协力。新政权、新公司的建立。倪师讲鼎有三足，代表必须有三股力量、三个得力干将互相配合，方能稳固。三足大鼎缺一不可。一个人撑不起一个新事业。", ImageReading: "三足大鼎（稳固结构）、烹饪新生（建设新局）、三方协作。"},
	{Number: 51, Name: "震为雷", HumanWay: "警示震惊，临惊不乱。恐惧修省。倪师说雷声虽大，但\"震惊百里，不丧匕鬯\"——真正心里有底、行得正的君子，打雷也吓不倒他。突发巨变时，心不乱就没事。", ImageReading: "雷声隆隆（突发震惊）、突发巨变（不可预料）、虚惊一场。"},
	{Number: 52, Name: "艮为山", HumanWay: "止其所当止，保持冷静。动静不失其时。倪师说人生最难的是\"止\"——看到危险要止，欲望来了要止，不该说的话要止。两山对峙——内力和外力都在告诉你：够了，该停了。", ImageReading: "两山对峙（内外皆止）、止步不前（服从阻力）、静心克制。"},
	{Number: 53, Name: "风山渐", HumanWay: "循序渐进，婚姻大吉。倪师讲渐卦是女孩子出嫁最正、最吉的卦。像鸿雁飞行一样有条不紊，一步一个脚印。事业和婚姻都大吉。风在山间缓缓而行，不疾不徐。", ImageReading: "鸿雁飞翔（成双成对）、按部就班（不急不躁）、迎亲嫁娶。"},
	{Number: 54, Name: "雷泽归妹", HumanWay: "名不正言不顺，结局难全。少女（兑）追长男（震）。倪师在《天纪》中常批此卦：名不正（如偏房、未婚先孕、不正当合作），开始看起来很快乐，最后必凶。跛能履是勉强行走——硬撑着走，终究走不远。", ImageReading: "跛足勉强行走（撑不下去）、无名分（名不正言不顺）、婚姻凶兆。"},
	{Number: 55, Name: "雷火丰", HumanWay: "盛极必衰，日中则昃。丰收盛大到了极点。倪师提醒：丰卦之后就是旅卦（流亡），所以在最赚钱、最得意的时候，要看到背后的阴影。太阳到了正午虽然最亮，但接下去就要往西落了——日中则昃，月盈则亏。", ImageReading: "日丽中天但有乌云（盛极必衰）、财富满堂（危机暗藏）。"},
	{Number: 56, Name: "火山旅", HumanWay: "羁旅漂泊，客居他乡。山上有火，烧完就走——不在此地久留。倪师讲这是流亡、出差、做流动作业的卦。在外要谦逊柔顺，否则会招来杀身之祸。火蔓延不留，一轮烧完就要换地方。", ImageReading: "火蔓延不留（一轮过后换地方）、异乡漂泊、居无定所。"},
	{Number: 57, Name: "巽为风", HumanWay: "顺服深入，能屈能伸。风无孔不入。倪师说，做事情要像风一样深入到基层和细节中去。听从上级的正确决定，委婉地表达自己的意见。两风相随——重重深入，无微不至。", ImageReading: "两风相随（层层渗透）、无孔不入（细节到位）、顺从入微。"},
	{Number: 58, Name: "兑为泽", HumanWay: "喜悦交流，言语生财。两个沼泽互相滋润。倪师说\"兑\"就是吃吃喝喝、开开心心地沟通——谈判桌上最容易成事。但要提防流于口舌、谄媚之嫌。两泽相依说明人际关系极佳，但水太满就会溢出——嘴巴说太多也会惹祸。", ImageReading: "两泽相依（人际融洽）、喜笑颜开（谈判顺利）、饮食宴乐。"},
	{Number: 59, Name: "风水涣", HumanWay: "离散解除，拯救危机。风吹水面，洪水分流。倪师说，人心散了（涣）的时候，必须要\"用大牲\"或者\"建侯\"——用信仰、企业文化或者强有力的领导者把大家重新凝聚起来。大船渡河就是重新团结的象征——只要有船，散开的水面上的人都能渡到对岸。", ImageReading: "洪水分流（人心涣散）、大船渡河（团结渡难关）。"},
	{Number: 60, Name: "水泽节", HumanWay: "节制适度，不可过苦。泽中有水，水满了就要节制。倪师说制度、花钱都要有节制；但如果节制得太痛苦（苦节），这个制度就长久不了。竹节分明——节也有\"阶段\"的意思，按阶段前进。", ImageReading: "竹节分明（张弛有度）、有限度（不要太过）、切勿过分。"},
	{Number: 61, Name: "风泽中孚", HumanWay: "诚信感物，中心虚空。豚鱼吉。倪师讲中孚是内心极其诚信——不仅能感动人，连猪和鱼都能被你感动。做人做事，诚信是唯一的通行证。鸟抱卵（孵化之象）——诚心等待，能孕育出新的成果。", ImageReading: "鸟抱卵（诚心坚持）、内中虚空（谦虚心态）、大信（立身之本）。"},
	{Number: 62, Name: "雷山小过", HumanWay: "小有过错，宜下不宜上。飞鸟遗之音。倪师说这时候不要想做大事，做点小事、低调路过就好。宁可过于节俭、过于悲伤，也不要越位。飞鸟过空——低调通过，不要招惹是非。", ImageReading: "飞鸟过空（低调通过）、小错小过（不要紧张）、宜守不宜攻。"},
	{Number: 63, Name: "水火既济", HumanWay: "大功告成，初吉终乱。水在火上，饭煮熟了——大功告成。倪师说既济是全经最完美的平衡，但\"物极必反\"——最完美的时候往往就是走下坡路的开始。饭煮熟了不马上吃，就会凉掉焦掉。", ImageReading: "水火交融（完美平衡）、万事具备（小心变局）、提防走下坡路。"},
	{Number: 64, Name: "水火未济", HumanWay: "无限循环，希望在前方。火在水上，互不相交——饭没煮熟。倪师说未济代表没成功，但这才是《易经》的伟大之处！它不以完美终结，而是留个尾巴，让你有新的动力去开启下一个循环。火在上水在下，说明阴阳未和，但你有动力去改变。", ImageReading: "火水不交（尚未完成）、全新起点（积极开始）、无限可能。"},
}
